@Mapper(componentModel = "spring")               // generated at compile time
public interface UserMapper {
    @Mapping(source = "fullName", target = "name")
    UserDto toDto(User user);

    @Mapping(source = "name", target = "fullName")
    User fromDto(UserDto dto);
}

public final class UserMapper {                  // one class owns the mapping
    public UserDto toDto(User u) {
        return new UserDto(u.id(), u.fullName(), u.isAdmin());
    }
    public User fromDto(UserDto d) {
        return new User(d.id(), d.name(), d.isAdmin().orElse(false));
    }
}
